107	            const std::string& val = it->second;
108	
109	            // 白名单校验
110	            if (!spec.allowed_values.empty()) {
111	                bool found = false;
112	                for (const auto& allowed : spec.allowed_values) {
113	                    if (val == allowed) {
114	                        found = true;
115	                        break;
116	                    }
117	                }
118	                if (!found) {
119	                    return {false, "Parameter '" + spec.name + "' value '" + val + "' is not in allowed list for " + action_id};
