173	    /**
174	     * @brief 严格通过 posix_spawn / execve 数组直接调用外部命令
175	     * 绝不经过任何 shell，彻底消除 shell 元字符与命令注入隐患。
176	     * 使用 poll() 并行异步读取 stdout 与 stderr 管道，避免死锁并实施超时强杀机制。
177	     */
178	    static ExecutionResult safeExec(const ExecSpec& spec, int timeout_seconds = 5) {
179	        ExecutionResult result;
180	        if (spec.executable.empty() || spec.argv.empty()) {
181	            result.error = "Executable or argv empty";
182	            return result;
183	        }
184	
185	        int out_pipe[2];
186	        int err_pipe[2];
187	        if (pipe(out_pipe) < 0) {
188	            result.error = "Failed to create stdout pipe";
189	            return result;
190	        }
191	        if (pipe(err_pipe) < 0) {
192	            close(out_pipe[0]);
193	            close(out_pipe[1]);
194	            result.error = "Failed to create stderr pipe";
195	            return result;
196	        }
197	
198	        posix_spawn_file_actions_t actions;
199	        posix_spawn_file_actions_init(&actions);
200	        posix_spawn_file_actions_addclose(&actions, out_pipe[0]);
201	        posix_spawn_file_actions_adddup2(&actions, out_pipe[1], STDOUT_FILENO);
202	        posix_spawn_file_actions_addclose(&actions, out_pipe[1]);
203	
204	        posix_spawn_file_actions_addclose(&actions, err_pipe[0]);
205	        posix_spawn_file_actions_adddup2(&actions, err_pipe[1], STDERR_FILENO);
206	        posix_spawn_file_actions_addclose(&actions, err_pipe[1]);
207	
208	        // 构建 argv 原始指针数组
209	        std::vector<char*> c_argv;
210	        for (const auto& arg : spec.argv) {
211	            c_argv.push_back(const_cast<char*>(arg.c_str()));
212	        }
213	        c_argv.push_back(nullptr);
214	
215	        pid_t pid = 0;
216	        int ret = posix_spawn(&pid, spec.executable.c_str(), &actions, nullptr, c_argv.data(), ::environ);
217	        posix_spawn_file_actions_destroy(&actions);
218	
219	        // 父进程关闭写端
220	        close(out_pipe[1]);
221	        close(err_pipe[1]);
222	
223	        if (ret != 0) {
224	            close(out_pipe[0]);
225	            close(err_pipe[0]);
226	            result.error = "posix_spawn failed with error: " + std::to_string(ret);
227	            return result;
228	        }
229	
230	        // 将读端设置为非阻塞，防止 read() 阻塞
231	        auto set_nonblocking = [](int fd) {
232	            int flags = fcntl(fd, F_GETFL, 0);
233	            if (flags >= 0) {
234	                fcntl(fd, F_SETFL, flags | O_NONBLOCK);
235	            }
236	        };
237	        set_nonblocking(out_pipe[0]);
238	        set_nonblocking(err_pipe[0]);
239	
240	        struct pollfd pfd[2];
241	        pfd[0].fd = out_pipe[0];
242	        pfd[0].events = POLLIN;
243	        pfd[1].fd = err_pipe[0];
244	        pfd[1].events = POLLIN;
245	
246	        int open_fds = 2;
247	        auto start_time = std::chrono::steady_clock::now();
248	        const auto timeout_duration = std::chrono::seconds(std::max(1, timeout_seconds));
249	
250	        while (open_fds > 0) {
251	            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
252	                std::chrono::steady_clock::now() - start_time);
253	            auto total_ms = std::chrono::duration_cast<std::chrono::milliseconds>(timeout_duration);
254	            int remaining_ms = static_cast<int>(total_ms.count() - elapsed.count());
255	
256	            if (remaining_ms <= 0) {
257	                // 超时强制杀死子进程
258	                kill(pid, SIGKILL);
259	                result.timed_out = true;
260	                result.error = "Execution timed out after " + std::to_string(timeout_seconds) + " seconds";
261	                break;
262	            }
263	
264	            int pr = poll(pfd, 2, std::min(remaining_ms, 200));
265	            if (pr < 0) {
266	                if (errno == EINTR) continue;
267	                result.error = "poll failed: " + std::string(strerror(errno));
268	                kill(pid, SIGKILL);
269	                break;
270	            }
271	
272	            // 读取 stdout
273	            if (pfd[0].fd >= 0 && (pfd[0].revents & (POLLIN | POLLHUP | POLLERR))) {
274	                char buf[512];
275	                ssize_t n = 0;
276	                while ((n = read(pfd[0].fd, buf, sizeof(buf))) > 0) {
277	                    result.stdout_output.append(buf, n);
278	                }
279	                if (n == 0 || (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK)) {
280	                    close(pfd[0].fd);
281	                    pfd[0].fd = -1;
282	                    open_fds--;
283	                }
284	            }
285	
286	            // 读取 stderr
287	            if (pfd[1].fd >= 0 && (pfd[1].revents & (POLLIN | POLLHUP | POLLERR))) {
288	                char buf[512];
289	                ssize_t n = 0;
290	                while ((n = read(pfd[1].fd, buf, sizeof(buf))) > 0) {
291	                    result.stderr_output.append(buf, n);
292	                }
293	                if (n == 0 || (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK)) {
294	                    close(pfd[1].fd);
295	                    pfd[1].fd = -1;
296	                    open_fds--;
297	                }
298	            }
299	        }
300	
301	        if (pfd[0].fd >= 0) close(pfd[0].fd);
302	        if (pfd[1].fd >= 0) close(pfd[1].fd);
303	
304	        int status = 0;
305	        waitpid(pid, &status, 0);
306	        if (WIFEXITED(status)) {
307	            result.exit_code = WEXITSTATUS(status);
308	        } else if (WIFSIGNALED(status)) {
309	            result.exit_code = 128 + WTERMSIG(status);
310	        }
311	
312	        return result;
313	    }
