352	            },
353	            "/sbin/ip",
354	            {"link", "set", "@{interface}", "up"}
355	        });
356	    }
357	
358	    std::map<std::string, ActionDef> actions_;
359	};
360	
361	/// 动作目录内容指纹（SHA-256 前 12 位十六进制）。
362	///
363	/// 覆盖两部分：动作目录（action_id + 参数规范）与 TRIAL 配置键白名单——
364	/// 即"网关声称自己能执行什么"。云端持有同算法、同规范 JSON 的实现
365	/// （`edge_action_catalog.catalog_version()`），两侧指纹不等即部署版本漂移，
366	/// 由 Policy fail-closed 拒绝执行（见 docs/网关动作目录版本契约.md）。
367	///
368	/// 实现在 action_registry.cpp，OpenSSL 类型不出现在本头文件。
369	std::string actionCatalogVersion(const ActionRegistry& registry);
370	
371	/// 规范载荷（指纹的输入）。单独暴露是给跨端一致性测试用：
372	/// 两端比对的是"逐字节相同的载荷"，而不只是"恰好相等的哈希"——
373	/// 哈希相等而载荷不同的情况一旦出现，说明算法已经分叉。
374	std::string actionCatalogCanonicalPayload(const ActionRegistry& registry);
375	
376	} // namespace weaknet
