552	bool EdgeTelemetryExporter::postSigned(const std::string& url, const std::string& body,
553	                                        const std::string& signature, std::string* response,
554	                                        std::string* error) {
555	#ifdef WEAKNET_HAVE_CURL
556	    CURL* curl = curl_easy_init();
557	    if (!curl) {
558	        *error = "curl_easy_init 失败";
559	        return false;
560	    }
561	
562	    struct curl_slist* headers = nullptr;
563	    headers = curl_slist_append(headers, "Content-Type: application/json");
564	    const std::string key_header = "X-Edge-Key-Id: " + config_.edge.key_id.get();
565	    const std::string token_header = "X-Edge-Token: " + config_.edge.token.get();
566	    const std::string tenant_header = "X-Edge-Tenant: " + config_.edge.tenant.get();
567	    const std::string sig_header = "X-Edge-Signature: " + signature;
568	    headers = curl_slist_append(headers, key_header.c_str());
569	    headers = curl_slist_append(headers, token_header.c_str());
570	    headers = curl_slist_append(headers, tenant_header.c_str());
571	    headers = curl_slist_append(headers, sig_header.c_str());
572	
573	    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
574	    curl_easy_setopt(curl, CURLOPT_POST, 1L);
575	    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body.data());
576	    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, static_cast<long>(body.size()));
577	    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
578	    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
579	    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
580	    // 显式超时：绝不允许上报线程因对端无响应而长时间挂起。
581	    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS,
582	                     static_cast<long>(config_.edge.timeout_ms.load()));
583	    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT_MS,
584	                     static_cast<long>(config_.edge.timeout_ms.load()));
585	
586	    const CURLcode code = curl_easy_perform(curl);
587	    long http_status = 0;
588	    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_status);
589	    curl_slist_free_all(headers);
590	    curl_easy_cleanup(curl);
591	
592	    if (code != CURLE_OK || http_status < 200 || http_status >= 300) {
593	        *error = std::string("上报失败: ") + curl_easy_strerror(code) +
594	                 " http=" + std::to_string(http_status);
595	        return false;
596	    }
597	    return true;
598	#else
599	    (void)url; (void)body; (void)signature; (void)response;
600	    *error = "本构建未链接 libcurl，无法发送";
601	    return false;
602	#endif
603	}
