605	bool EdgeTelemetryExporter::transmit(const std::vector<EdgeTelemetryRecord>& records,
606	                                    std::string* error) {
607	    if (records.empty()) return true;
608	
609	#ifdef WEAKNET_HAVE_CURL
610	    // 批量补发时，body 取"最后一条"的签名对应的字节；因此批量场景下
611	    // 每条记录单独发送，而不是拼成一个巨大请求——拼接会破坏
612	    // "签名覆盖发送字节"这一不变式。
613	    for (const auto& record : records) {
614	        if (stop_requested_.load()) {
615	            if (error) *error = "stop_requested";
616	            return false;
617	        }
618	        std::string response;
619	        if (!postSigned(config_.edge.url.get(), record.body, record.signature,
620	                        &response, error)) {
621	            return false;
622	        }
623	
624	        if (stop_requested_.load()) {
625	            return false;
626	        }
627	        applyPendingActions(response);
628	
629	        {
630	            std::lock_guard<std::mutex> lock(stats_mutex_);
631	            stats_.snapshots_sent++;
632	        }
633	    }
634	    return true;
635	#else
636	    *error = "本构建未链接 libcurl，无法发送";
637	    return false;
638	#endif  // WEAKNET_HAVE_CURL
639	}
