641	void EdgeTelemetryExporter::applyPendingActions(const std::string& response_body) {
642	    const auto actions = parsePendingActions(response_body);
643	    if (actions.empty()) return;
644	
645	    for (const auto& action : actions) {
646	        std::string error;
647	        bool ok = false;
648	
649	        const bool trialable = weaknet_dbus::isTrialableKey(action.key);
650	        const bool v2_metadata = action.generation_present || !action.claim_token.empty() ||
651	                                 !action.nonce.empty();
652	
653	        // 应答丢失→遥测重发→云端重放 pending_actions 是常态路径。
654	        // 已执行过的 action_id 回执**首次的真实结果**，绝不重执行（重执行会重置
655	        // TRIAL deadline、把看门狗无限续期，并泛洪 action-results）。
656	        // 注意：不能固定回 APPLIED——首次被拒的动作若谎报成功，云端会把
657	        // 未生效的配置记成已应用。
658	        auto it = executed_action_ids_.find(action.action_id);
659	        if (it != executed_action_ids_.end()) {
660	            const bool first_ok = it->second;
661	            LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
662	                     "云端动作已执行过，直接回执不重放: " << action.action_id
663	                     << " (first=" << (first_ok ? "APPLIED" : "REJECTED") << ")");
664	            queueActionResult(action.action_id, first_ok ? "APPLIED" : "REJECTED",
665	                              first_ok ? "applied_duplicate" : "rejected_duplicate",
666	                              action.claim_token, action.generation);
667	            continue;
668	        }
669	
670	        // fail-closed：trialable key 或携带 v2 元数据的动作必须带有效 generation，
671	        // 否则 generation=0 会绕过 stale 判定、且永远推进不了 last_applied。
672	        if ((trialable || v2_metadata) && (!action.generation_present || action.generation == 0)) {
673	            error = "missing_or_invalid_generation";
674	        } else {
675	            const bool stale = action.generation > 0 &&
676	                               config_txn_ &&
677	                               action.generation <= config_txn_->lastAppliedGeneration();
678	
679	        if (stale) {
680	            error = "stale_generation";
681	            LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
682	                      "云端动作被拒绝（generation 过期）: " << action.key
683	                      << " gen=" << action.generation
684	                      << " last=" << config_txn_->lastAppliedGeneration());
685	        } else if (trialable && config_txn_) {
686	            // TRIAL 路径：先记账（含 prior_values 快照），再落值。
687	            auto* cfg = const_cast<weaknet_dbus::WeakNetConfig*>(&config_);
688	            const auto state = config_txn_->state();
689	            if (state == weaknet_dbus::ConfigState::TRIAL) {
690	                ok = config_txn_->extendTrial(*cfg, action.key, action.value,
691	                                              action.action_id, action.generation,
692	                                              &error);
693	            } else {
694	                ok = config_txn_->startTrial(*cfg, action.key, action.value,
695	                                             action.action_id, action.generation,
696	                                             &error);
697	            }
698	            if (ok) {
699	                ok = weaknet_dbus::setMonitorParam(cfg, action.key, action.value, &error);
700	            }
701	        } else {
702	            // 直通道：非 trialable key 直接走 setMonitorParam。
703	            ok = weaknet_dbus::setMonitorParam(
704	                const_cast<weaknet_dbus::WeakNetConfig*>(&config_),
705	                action.key, action.value, &error);
706	        }
707	        }
708	
709	        if (ok) {
710	            // 两条应用路径（TRIAL 记账 / 直通道）都必须推进防重放高水位；
711	            // 否则 last_applied 永远停在 confirmStable/forceRollback 之前，
712	            // 云端因应答丢失重放同一代次时会被重新执行。
713	            if (config_txn_ && action.generation > 0) {
714	                config_txn_->markGenerationApplied(action.generation);
715	            }
716	            // 去重表只记录成功应用的 action：被拒动作允许重试，
717	            // 重放时重新走完整执行路径（会再次被拒并回执 REJECTED）。
718	            // 容量上限防无界增长：超过 1024 条时清空最旧的一批（直接 clear，
719	            // 重启都会清空，云端已终态的历史动作即便偶发漏判重做也受 generation 门禁守卫）。
720	            if (executed_action_ids_.size() >= 1024) {
721	                executed_action_ids_.clear();
722	            }
723	            executed_action_ids_.emplace(action.action_id, true);
724	            LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
725	                     "已应用服务端下发的配置: " << action.key << "=" << action.value
726	                     << " (action=" << action.action_id
727	                     << " gen=" << action.generation
728	                     << (trialable && config_txn_ ? " [TRIAL]" : " [DIRECT]") << ")");
729	        } else {
730	            if (!error.empty() && error != "stale_generation" &&
731	                error != "missing_or_invalid_generation") {
732	                LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
733	                          "服务端下发配置被拒绝: " << action.key << "=" << action.value
734	                          << " (action=" << action.action_id << ", " << error << ")");
735	            }
736	        }
737	
738	        {
739	            std::lock_guard<std::mutex> lock(stats_mutex_);
740	            if (ok) {
741	                stats_.actions_applied++;
742	            } else {
743	                stats_.actions_rejected++;
744	            }
745	        }
746	
747	        // 无论应用成功与否都必须回执：服务端靠它把 action 推进到
748	        // APPLIED/REJECTED，缺了回执这条 action 会停在 DELIVERED 永远不完结。
749	        queueActionResult(action.action_id, ok ? "APPLIED" : "REJECTED",
750	                          ok ? "applied" : error,
751	                          action.claim_token, action.generation);
752	    }
753	}
