755	void EdgeTelemetryExporter::queueActionResult(const std::string& action_id, const char* status,
756	                                               const std::string& detail,
757	                                               const std::string& claim_token,
758	                                               uint64_t generation,
759	                                               const std::string& config_key,
760	                                               const std::string& config_value) {
761	    EdgeActionResultRecord rec;
762	    rec.action_id = action_id;
763	    rec.status = status;
764	    rec.detail = detail;
765	
766	    const auto now_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
767	        std::chrono::system_clock::now().time_since_epoch()).count();
768	
769	    std::ostringstream body;
770	    body << "{\"schema_version\":\"network.edge.action-results.v2\",";
771	    body << "\"device_id\":\"" << weaknet_utils::escapeJsonString(config_.edge.device_id.get()) << "\",";
772	    body << "\"results\":[{";
773	    body << "\"action_id\":\"" << weaknet_utils::escapeJsonString(action_id) << "\",";
774	    body << "\"status\":\"" << rec.status << "\",";
775	    body << "\"detail\":\"" << weaknet_utils::escapeJsonString(detail) << "\",";
776	    body << "\"claim_token\":\"" << weaknet_utils::escapeJsonString(claim_token) << "\",";
777	    body << "\"generation\":" << generation << ",";
778	    // 仅本地变更携带：云端下发的动作由服务端从 network_pending_actions 回读
779	    // key/value，两处来源同时写会互相打架。空串 = 不写该字段。
780	    if (!config_key.empty()) {
781	        body << "\"config_key\":\"" << weaknet_utils::escapeJsonString(config_key) << "\",";
782	        body << "\"config_value\":\"" << weaknet_utils::escapeJsonString(config_value) << "\",";
783	    }
784	    body << "\"reported_at\":\"" << formatRfc3339Utc(now_ms) << "\"}]}";
785	    rec.body = body.str();
786	
787	    std::string sign_error;
788	    rec.signature = signBody(rec.body, &sign_error);
789	    if (rec.signature.empty()) {
790	        LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
791	                  "动作结果签名失败，无法回执: action=" << action_id << " (" << sign_error << ")");
792	        return;
793	    }
794	
795	    {
796	        std::lock_guard<std::mutex> lock(mutex_);
797	        pending_action_results_.push_back(std::move(rec));
798	    }
799	    cv_.notify_one();
800	}
