/// 从响应体中提取全部 pending_actions（动作对象数组，保序）。
///
/// 每个动作对象携带 {action_id, key, value, generation, nonce, claim_token}
/// 六个字段。generation/nonce 是云端下发的防重放/防乱序元数据；缺失时
/// 取 0/""（与 v1 schema 兼容）。
struct PendingAction {
    std::string action_id;
    std::string key;
    std::string value;
    uint64_t generation{0};
    bool generation_present{false};  ///< generation 字段是否在报文中真实出现且解析成功
    std::string nonce;
    std::string claim_token;
};

/// 提取 JSON 对象内的 uint64 字段；缺失或非法返回 false。
bool extractUint64Field(const std::string& json, const std::string& key,
                        uint64_t* out) {
    const std::string needle = "\"" + key + "\"";
    size_t pos = json.find(needle);
    if (pos == std::string::npos) return false;
    pos = json.find(':', pos + needle.size());
    if (pos == std::string::npos) return false;
    ++pos;
    while (pos < json.size() && std::isspace(static_cast<unsigned char>(json[pos]))) ++pos;
    if (pos >= json.size() || !std::isdigit(static_cast<unsigned char>(json[pos]))) {
        return false;
    }
    uint64_t value = 0;
    while (pos < json.size() && std::isdigit(static_cast<unsigned char>(json[pos]))) {
        const uint64_t digit = static_cast<uint64_t>(json[pos] - '0');
        if (value > (UINT64_MAX - digit) / 10) {
            return false; // 溢出防御：数字超出 uint64 范围直接拒绝，绝不猜测
        }
        value = value * 10 + digit;
        ++pos;
    }
    *out = value;
    return true;
}

std::vector<PendingAction> parsePendingActions(const std::string& body) {
    std::vector<PendingAction> actions;
    const std::string array_key = "\"pending_actions\"";
    size_t pos = body.find(array_key);
    if (pos == std::string::npos) return actions;

    // 寻找 pending_actions 数组的开括号 '[' 与闭括号 ']'，限制解析范围在数组内，
    // 避免误把响应体其它顶层对象或嵌套字段里的 action_id 误认为下行动作。
    // 防御处理：忽略双引号字符串内部的 ']' 字符，保证数组边界准确。
    const size_t array_start = body.find('[', pos + array_key.size());
    if (array_start == std::string::npos) return actions;
    size_t array_end = std::string::npos;
    bool in_string = false;
    bool escaped = false;
    for (size_t i = array_start + 1; i < body.size(); ++i) {
        char c = body[i];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (c == '\\') {
            escaped = true;
            continue;
        }
        if (c == '"') {
            in_string = !in_string;
            continue;
        }
        if (c == ']' && !in_string) {
            array_end = i;
            break;
        }
    }
    if (array_end == std::string::npos) return actions;

    pos = array_start + 1;
    while (pos < array_end) {
        PendingAction action;
        size_t cursor = pos;
        // 每个动作对象内同时含 action_id / key / value / generation /
        // nonce / claim_token；用 action_id 作为分段锚点，避免跨对象误取。
        if (!extractStringField(body, "action_id", cursor, &action.action_id, &cursor)) break;
        if (cursor >= array_end) break;
        // 该动作对象在本段内查找其它字段；边界取下一个 action_id 或数组闭括号之前。
        const size_t next_action = body.find("\"action_id\"", cursor);
        const size_t segment_end = (next_action == std::string::npos || next_action > array_end)
                                       ? array_end
                                       : next_action;
        const std::string segment = body.substr(cursor, segment_end - cursor);
        if (!extractStringField(segment, "key", 0, &action.key, nullptr)) { pos = segment_end; continue; }
        if (!extractStringField(segment, "value", 0, &action.value, nullptr)) { pos = segment_end; continue; }
        // v2 元数据可选：缺失视为 0/""（与 v1 兼容）。
        // generation 必须**确实存在于本动作段**且解析成功才算携带了防重放元数据；
        // 解析失败时保留 0 并靠 generation_present_ 区分"未提供"与"提供了 0"，
        // 供 applyPendingActions 的 fail-closed 门禁使用。
        if (extractUint64Field(segment, "generation", &action.generation)) {
            action.generation_present = true;
        } else {
            action.generation = 0;
        }
        extractStringField(segment, "nonce", 0, &action.nonce, nullptr);
        extractStringField(segment, "claim_token", 0, &action.claim_token, nullptr);
        actions.push_back(std::move(action));
        pos = segment_end;
        if (next_action == std::string::npos || next_action >= array_end) break;
    }
    return actions;
}

